    49	    public synchronized Reservation create(NewReservation request) {
    50	        if (!request.checkOut().isAfter(request.checkIn())) {
    51	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
    52	        }
    53	        if (request.guests() < 1) {
    54	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
    55	        }
    56	        Room room = rooms.find(request.roomNumber())
    57	                .orElseThrow(() -> new HotelException(
    58	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
    59	        if (request.guests() > room.capacity()) {
    60	            throw new HotelException(
    61	                    ErrorCode.CAPACITY_EXCEEDED,
    62	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
    63	        }
