    65	            throw new HotelException(
    66	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
    67	        }
    68	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan());
    69	        return store.add(request, price);
    70	    }
